import{_ as t,o as d,c as o,ae as a}from"./chunks/framework.C4zpkcTP.js";const l=JSON.parse('{"title":"Results","description":"Field reference for RedirectPayment, FormPayment, QrPayment and AppPayment, the result types returned when a payment is started.","frontmatter":{"title":"Results","description":"Field reference for RedirectPayment, FormPayment, QrPayment and AppPayment, the result types returned when a payment is started."},"headers":[],"relativePath":"goravel-myanmar-payments/references/results.md","filePath":"goravel-myanmar-payments/references/results.md"}'),r={name:"goravel-myanmar-payments/references/results.md"};function c(n,e,s,i,m,p){return d(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="results" tabindex="-1">Results <a class="header-anchor" href="#results" aria-label="Permalink to &quot;Results&quot;">​</a></h1><p>Starting a payment returns a pointer to one of four types in <code>github.com/laranex/go-myanmar-payments/v4</code> (imported as <code>myanmarpayments</code>). All implement <code>PaymentResult</code> and expose <code>Flow() PaymentFlow</code>.</p><h2 id="redirectpayment" tabindex="-1">RedirectPayment <a class="header-anchor" href="#redirectpayment" aria-label="Permalink to &quot;RedirectPayment&quot;">​</a></h2><p>Returned by <code>KbzPay()</code> → <code>PWA()</code> and <code>WaveMoney()</code> → <code>Initiate()</code>.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>OrderID</code></td><td><code>string</code></td><td>Your order ID</td></tr><tr><td><code>URL</code></td><td><code>string</code></td><td>The gateway page to redirect the customer to</td></tr><tr><td><code>GatewayReference</code></td><td><code>string</code></td><td>The gateway&#39;s ID for this attempt (KBZ <code>prepay_id</code>, Wave <code>transaction_id</code>)</td></tr><tr><td><code>Raw</code></td><td><code>map[string]any</code></td><td>The gateway&#39;s response, for logging</td></tr></tbody></table><h2 id="formpayment" tabindex="-1">FormPayment <a class="header-anchor" href="#formpayment" aria-label="Permalink to &quot;FormPayment&quot;">​</a></h2><p>Returned by <code>AyaPay()</code> → <code>Initiate()</code> and <code>CyberSource()</code> → <code>Initiate()</code>.</p><table tabindex="0"><thead><tr><th>Field / Method</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>OrderID</code></td><td><code>string</code></td><td>Your order ID</td></tr><tr><td><code>Action</code></td><td><code>string</code></td><td>The gateway URL the form posts to</td></tr><tr><td><code>Fields</code></td><td><code>[]FormField</code></td><td>The signed hidden fields (<code>Name</code>, <code>Value</code>), in signing order. Post them unchanged</td></tr><tr><td><code>Enctype</code></td><td><code>string</code></td><td>The form encoding the gateway expects. <code>HTML()</code> treats an empty value as <code>application/x-www-form-urlencoded</code></td></tr><tr><td><code>Field(name)</code></td><td><code>(string, bool)</code></td><td>The value of one field</td></tr><tr><td><code>Values()</code></td><td><code>map[string]string</code></td><td>The fields as a map</td></tr><tr><td><code>HTML()</code></td><td><code>string</code></td><td>A full HTML page that posts the form on load</td></tr></tbody></table><p><code>payments.AutoSubmitURL(form)</code> returns the link to the package&#39;s auto-submitting page; it returns <code>payments.ErrFormRouteDisabled</code> when the form route is disabled.</p><h2 id="qrpayment" tabindex="-1">QrPayment <a class="header-anchor" href="#qrpayment" aria-label="Permalink to &quot;QrPayment&quot;">​</a></h2><p>Returned by <code>KbzPay()</code> → <code>QR()</code>, <code>YomaMmqr()</code> → <code>Initiate()</code> and <code>YomaMmqr()</code> → <code>RenewQR()</code>.</p><table tabindex="0"><thead><tr><th>Field / Method</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>OrderID</code></td><td><code>string</code></td><td>Your order ID</td></tr><tr><td><code>QRString</code></td><td><code>string</code></td><td>A QR payload to encode yourself (KBZ Pay)</td></tr><tr><td><code>QRImage</code></td><td><code>string</code></td><td>A base64 image to display as is (Yoma MMQR)</td></tr><tr><td><code>ExpiresAt</code></td><td><code>time.Time</code></td><td>When the QR stops being payable. Zero when the gateway does not limit it</td></tr><tr><td><code>Reference</code></td><td><code>string</code></td><td>The gateway&#39;s ID for this QR (KBZ <code>prepay_id</code>, Yoma <code>refLabel</code>)</td></tr><tr><td><code>Raw</code></td><td><code>map[string]any</code></td><td>The gateway&#39;s response, for logging</td></tr><tr><td><code>QRImageDataURI(mimeType)</code></td><td><code>string</code></td><td><code>QRImage</code> as a data URI for <code>&lt;img src&gt;</code>. An empty <code>mimeType</code> means <code>image/png</code></td></tr></tbody></table><h2 id="apppayment" tabindex="-1">AppPayment <a class="header-anchor" href="#apppayment" aria-label="Permalink to &quot;AppPayment&quot;">​</a></h2><p>Returned by <code>KbzPay()</code> → <code>App()</code>.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>OrderID</code></td><td><code>string</code></td><td>Your order ID</td></tr><tr><td><code>OrderInfo</code></td><td><code>string</code></td><td>The signed order string the SDK expects</td></tr><tr><td><code>Sign</code></td><td><code>string</code></td><td>The signature of <code>OrderInfo</code></td></tr><tr><td><code>SignType</code></td><td><code>string</code></td><td><code>SHA256</code></td></tr><tr><td><code>Raw</code></td><td><code>map[string]any</code></td><td>The gateway&#39;s response, for logging</td></tr></tbody></table><p>Encoded as JSON, an <code>AppPayment</code> has <code>orderId</code>, <code>orderInfo</code>, <code>sign</code> and <code>signType</code> for your mobile app; <code>Raw</code> is left out.</p><h2 id="paymentflow" tabindex="-1">PaymentFlow <a class="header-anchor" href="#paymentflow" aria-label="Permalink to &quot;PaymentFlow&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Constant</th><th>Value</th><th>Result</th></tr></thead><tbody><tr><td><code>myanmarpayments.FlowRedirect</code></td><td><code>redirect</code></td><td><code>RedirectPayment</code></td></tr><tr><td><code>myanmarpayments.FlowForm</code></td><td><code>form</code></td><td><code>FormPayment</code></td></tr><tr><td><code>myanmarpayments.FlowQR</code></td><td><code>qr</code></td><td><code>QrPayment</code></td></tr><tr><td><code>myanmarpayments.FlowApp</code></td><td><code>app</code></td><td><code>AppPayment</code></td></tr></tbody></table>',18)])])}const h=t(r,[["render",c]]);export{l as __pageData,h as default};
